n = 6

# We'll represent the grid as a list of lists
# Each cell has a domain {0,...,5}
# Constraints:
# 1. Latin square (all different in rows and columns)
# 2. Diagonal: grid[i][i] = i
# 3. QG3: grid[grid[i][j]][grid[j][i]] = i

def solve():
    grid = [[None for _ in range(n)] for _ in range(n)]

    # Fix diagonal
    for i in range(n):
        grid[i][i] = i

    # Precompute which cells are constrained
    # For QG3, if we set grid[i][j] = a and grid[j][i] = b,
    # then grid[a][b] must equal i.

    def is_valid_partial():
        # Check rows and columns for duplicates
        for i in range(n):
            row_vals = [grid[i][j] for j in range(n) if grid[i][j] is not None]
            if len(row_vals) != len(set(row_vals)):
                return False
            col_vals = [grid[j][i] for j in range(n) if grid[j][i] is not None]
            if len(col_vals) != len(set(col_vals)):
                return False

        # Check QG3 for fully determined triples
        for i in range(n):
            for j in range(n):
                a = grid[i][j]
                b = grid[j][i]
                if a is not None and b is not None:
                    c = grid[a][b]
                    if c is not None and c != i:
                        return False

        return True

    def get_empty_cell():
        # Find empty cell with smallest domain (MRV heuristic)
        best = None
        best_domain_size = n + 1
        for i in range(n):
            for j in range(n):
                if grid[i][j] is None:
                    # Compute domain
                    used = set()
                    for k in range(n):
                        if grid[i][k] is not None:
                            used.add(grid[i][k])
                        if grid[k][j] is not None:
                            used.add(grid[k][j])
                    domain = [v for v in range(n) if v not in used]

                    # Also check QG3 implications
                    # If setting grid[i][j] = v, and grid[j][i] is known,
                    # then grid[v][grid[j][i]] must be i (if that cell is filled)

                    if len(domain) < best_domain_size:
                        best_domain_size = len(domain)
                        best = (i, j, domain)
                        if best_domain_size == 0:
                            return best
        return best

    def backtrack():
        if not is_valid_partial():
            return False

        cell = get_empty_cell()
        if cell is None:
            return True  # All cells filled

        i, j, domain = cell

        for val in domain:
            grid[i][j] = val

            # Also enforce QG3 implication if possible
            # grid[grid[i][j]][grid[j][i]] = i
            # If grid[j][i] is known, then grid[val][grid[j][i]] = i

            if backtrack():
                return True

            grid[i][j] = None

        return False

    if backtrack():
        return grid
    else:
        return None

