from z3 import *

def solve_qg3(n):
    x = [[Int(f"x_{i}_{j}") for j in range(n)] for i in range(n)]
    s = Solver()

    # Domain constraints
    for i in range(n):
        for j in range(n):
            s.add(x[i][j] >= 0, x[i][j] <= n-1)

    # Latin square
    for i in range(n):
        s.add(Distinct([x[i][j] for j in range(n)]))
    for j in range(n):
        s.add(Distinct([x[i][j] for i in range(n)]))

    # Idempotent diagonal
    for i in range(n):
        s.add(x[i][i] == i)

    # QG3 using Or/And encoding
    for i in range(n):
        for j in range(n):
            clauses = []
            for a in range(n):
                for b in range(n):
                    clauses.append(And(x[i][j] == a, x[j][i] == b, x[a][b] == i))
            s.add(Or(clauses))

    res = s.check()
    if res == sat:
        m = s.model()
        grid = []
        for i in range(n):
            row = []
            for j in range(n):
                row.append(m.evaluate(x[i][j]).as_long())
            grid.append(row)
        return grid
    else:
        return None

