def solve_qg3_backtrack(n):
    grid = [[None for _ in range(n)] for _ in range(n)]

    # Fix diagonal
    for i in range(n):
        grid[i][i] = i

    def get_possible_values(i, j):
        if grid[i][j] is not None:
            return [grid[i][j]]

        used = set()
        for k in range(n):
            if grid[i][k] is not None:
                used.add(grid[i][k])
            if grid[k][j] is not None:
                used.add(grid[k][j])

        possible = []
        for v in range(n):
            if v in used:
                continue

            # Check QG3 implications
            # If we set grid[i][j] = v:
            # 1. grid[v][grid[j][i]] = i (if grid[j][i] is known)
            # 2. grid[grid[j][i]][v] = j (from QG3 with swapped indices)
            # 3. grid[grid[i][j]][grid[j][i]] = i -> grid[v][grid[j][i]] = i

            valid = True

            # Check implication 1: grid[v][grid[j][i]] = i
            b = grid[j][i]
            if b is not None:
                c = grid[v][b]
                if c is not None and c != i:
                    valid = False

            # Check implication 2: from QG3 at (j,i): grid[grid[j][i]][grid[i][j]] = j
            # i.e., grid[b][v] = j
            if b is not None:
                c2 = grid[b][v]
                if c2 is not None and c2 != j:
                    valid = False

            # Check if setting this would create a conflict with other known QG3 constraints
            # For any k where grid[k][v] is known and grid[v][k] is known:
            # grid[grid[k][v]][grid[v][k]] = k
            # This is already checked in is_valid, but we can do more here

            if valid:
                possible.append(v)

        return possible

    def is_valid():
        # Check rows and columns for duplicates
        for i in range(n):
            row_vals = [grid[i][j] for j in range(n) if grid[i][j] is not None]
            if len(row_vals) != len(set(row_vals)):
                return False
            col_vals = [grid[j][i] for j in range(n) if grid[j][i] is not None]
            if len(col_vals) != len(set(col_vals)):
                return False

        # Check QG3 for fully determined triples
        for i in range(n):
            for j in range(n):
                a = grid[i][j]
                b = grid[j][i]
                if a is not None and b is not None:
                    c = grid[a][b]
                    if c is not None and c != i:
                        return False

        return True

    def select_unassigned():
        min_options = n + 1
        best = None
        for i in range(n):
            for j in range(n):
                if grid[i][j] is None:
                    opts = get_possible_values(i, j)
                    if len(opts) < min_options:
                        min_options = len(opts)
                        best = (i, j, opts)
                        if min_options == 0:
                            return best
        return best

    count = [0]

    def backtrack():
        count[0] += 1
        if count[0] % 100000 == 0:
            print(f"Nodes: {count[0]}")

        if not is_valid():
            return False

        cell = select_unassigned()
        if cell is None:
            return True

        i, j, options = cell

        for val in options:
            grid[i][j] = val

            # Forward checking: check if any empty cell now has no valid options
            fc_valid = True
            for ii in range(n):
                for jj in range(n):
                    if grid[ii][jj] is None:
                        opts = get_possible_values(ii, jj)
                        if len(opts) == 0:
                            fc_valid = False
                            break
                if not fc_valid:
                    break

            if fc_valid and backtrack():
                return True

            grid[i][j] = None

        return False

    if backtrack():
        return grid, count[0]
    else:
        return None, count[0]

