import pycosat

def solve_with_pycosat(n):
    # Variables: x[i][j][v] = True iff cell (i,j) has value v
    # Variable numbering: i*n*n + j*n + v + 1 (1-indexed for pycosat)
    def var(i, j, v):
        return i * n * n + j * n + v + 1

    clauses = []

    # Each cell has exactly one value
    for i in range(n):
        for j in range(n):
            # At least one value
            clauses.append([var(i, j, v) for v in range(n)])
            # At most one value
            for v1 in range(n):
                for v2 in range(v1 + 1, n):
                    clauses.append([-var(i, j, v1), -var(i, j, v2)])

    # Latin square: each row has all different values
    for i in range(n):
        for v in range(n):
            # Value v appears at least once in row i
            clauses.append([var(i, j, v) for j in range(n)])
            # Value v appears at most once in row i
            for j1 in range(n):
                for j2 in range(j1 + 1, n):
                    clauses.append([-var(i, j1, v), -var(i, j2, v)])

    # Latin square: each column has all different values
    for j in range(n):
        for v in range(n):
            # Value v appears at least once in column j
            clauses.append([var(i, j, v) for i in range(n)])
            # Value v appears at most once in column j
            for i1 in range(n):
                for i2 in range(i1 + 1, n):
                    clauses.append([-var(i1, j, v), -var(i2, j, v)])

    # Idempotent diagonal
    for i in range(n):
        clauses.append([var(i, i, i)])

    # QG3: x[x[i][j]][x[j][i]] = i
    # For all i,j: if x[i][j]=a and x[j][i]=b then x[a][b]=i
    for i in range(n):
        for j in range(n):
            for a in range(n):
                for b in range(n):
                    # -x[i][j][a] OR -x[j][i][b] OR x[a][b][i]
                    clauses.append([-var(i, j, a), -var(j, i, b), var(a, b, i)])

    print(f"n={n}: {len(clauses)} clauses")

    sol = pycosat.solve(clauses)
    if sol != "UNSAT":
        grid = [[None for _ in range(n)] for _ in range(n)]
        for lit in sol:
            if lit > 0:
                idx = lit - 1
                v = idx % n
                idx //= n
                j = idx % n
                idx //= n
                i = idx
                grid[i][j] = v
        return grid
    else:
        return None

